import 'package:flutter/material.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import 'package:introduction_screen/introduction_screen.dart';import '../../../../Core/Resources/app_colors.dart';import '../../../../Core/Utils/Extensions/localizations_extension.dart';import '../../../../Config/Assets/images.dart';import '../../../../Config/Routes/route_name.dart';import 'package:zan/main.dart';class BoardingScreen extends StatelessWidget {  const BoardingScreen({super.key});  @override  Widget build(BuildContext context) {    return Scaffold(      body: IntroductionScreen(        globalBackgroundColor: AppColors.backgroundColor,        pages: _buildPages(context),        showBackButton: true,        showSkipButton: false,        showNextButton: true,        next: _buildButton(context, context.appStrings.Next),        back: _buildButton(context, context.appStrings.Back),        dotsDecorator: _dotsDecoration(),        done: InkWell(            // onTap: () =>            //     kNavigationService.clearAndNavigateTo(AppRouteNames.start),            child: _buildButton(context, context.appStrings.Continue)),        showDoneButton: true,        onDone: () => kNavigationService.clearAndNavigateTo(AppRouteNames.start),      ),    );  }  List<PageViewModel> _buildPages(BuildContext context) {    return [      _buildPage(        title: context.appStrings.boarding1_title,        body: context.appStrings.boarding1_body,        image: AppImages.boarding1,      ),      _buildPage(        title: context.appStrings.boarding2_title,        body: context.appStrings.boarding2_body,        image: AppImages.boarding2,      ),      _buildPage(        title: context.appStrings.boarding3_title,        body: context.appStrings.boarding3_body,        image: AppImages.boarding3,      ),    ];  }  PageViewModel _buildPage(      {required String title, required String body, required String image}) {    return PageViewModel(      titleWidget: Column(        mainAxisAlignment: MainAxisAlignment.center,        children: [          Text(title,              textAlign: TextAlign.center,              style: TextStyle(                  fontSize: 22.sp,                  fontWeight: FontWeight.bold,                  color: Colors.white)),          SizedBox(height: 10.h),          Text(body,              textAlign: TextAlign.center,              style: TextStyle(fontSize: 14.sp, color: Colors.white70)),        ],      ),      bodyWidget: const SizedBox(),      image: _buildBackgroundImage(image),      decoration: _pageDecoration(),    );  }  DotsDecorator _dotsDecoration() {    return DotsDecorator(      size: Size(8.w, 8.h),      activeSize: Size(24.w, 8.h),      color: Colors.white54,      activeColor: Colors.white,      spacing: EdgeInsets.symmetric(horizontal: 4.w),      activeShape: RoundedRectangleBorder(        borderRadius: BorderRadius.circular(25.0),      ),    );  }  Widget _buildButton(BuildContext context, String text) {    return Container(      width: 0.8.sw,      height: 50.h,      decoration: BoxDecoration(        color: Colors.amber,        borderRadius: BorderRadius.circular(25),      ),      alignment: Alignment.center,      child: Text(text,          style: TextStyle(              fontSize: 16.sp,              fontWeight: FontWeight.bold,              color: Colors.black)),    );  }  PageDecoration _pageDecoration() {    return const PageDecoration(      fullScreen: true,      bodyFlex: 0,      imagePadding: EdgeInsets.zero,      contentMargin: EdgeInsets.zero,    );  }  Widget _buildBackgroundImage(String assetName) {    return Stack(      fit: StackFit.expand,      children: [        Image.asset(          assetName,          width: double.infinity,          height: double.infinity,          fit: BoxFit.cover,        ),        Container(color: Colors.black.withOpacity(0.3)),      ],    );  }}